import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.8tqBsFWt.js";const g=JSON.parse('{"title":"Onboarding a Project","description":"","frontmatter":{},"headers":[],"relativePath":"reference/workflows/onboarding-project.md","filePath":"reference/workflows/onboarding-project.md"}'),n={name:"reference/workflows/onboarding-project.md"};function s(i,e,l,h,p,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="onboarding-a-project" tabindex="-1">Onboarding a Project <a class="header-anchor" href="#onboarding-a-project" aria-label="Permalink to &quot;Onboarding a Project&quot;">​</a></h1><p>From &quot;we&#39;ve signed a new client&quot; to &quot;the team is logging time.&quot; All Owner steps unless noted.</p><p>Project setup happens in the <strong>web console</strong>. Creating projects, setting deadlines, assigning a PM, enabling tasks and distributing hours are all console operations — they are not things you ask VERA for in Slack. Slack is where the team logs and reviews their own time once the project exists.</p><hr><h2 id="step-1-create-the-project" tabindex="-1">Step 1: Create the project <a class="header-anchor" href="#step-1-create-the-project" aria-label="Permalink to &quot;Step 1: Create the project&quot;">​</a></h2><p>In the console, open <strong>Projects</strong> and choose <strong>New project</strong>.</p><ul><li><strong>Name</strong> — what the team will call it.</li><li><strong>Client</strong> — required. A new client is created automatically if the name is new. Choosing the <code>Internal</code> client locks the type to Internal.</li><li><strong>Type</strong> — <strong>T&amp;M</strong>, <strong>Fixed Price</strong>, <strong>Pro Bono</strong> or <strong>Internal</strong>. (Retainer and Agile are frozen: existing ones keep working and reporting, but new ones can&#39;t be created.)</li><li><strong>Contract value</strong> — required for Fixed Price.</li><li><strong>Hours budget</strong> — required for T&amp;M, Fixed Price and Pro Bono; optional for Internal.</li><li><strong>Deadline</strong> — required for T&amp;M, Fixed Price and Pro Bono; optional for Internal.</li></ul><p>The form will not submit until the fields your chosen type requires are filled, so there is no back-and-forth about missing values.</p><p><strong>Sizing a Fixed Price project.</strong> Enter a contract value and a billing rate and the form shows the hours that implies, with one click to fill the hours budget. It works in reverse too — a contract value plus an hours budget shows the implied billing rate. If that rate is at or below what your team costs to deliver, the readout turns red. The warning is advisory, not a gate.</p><hr><h2 id="step-2-confirm-the-deadline" tabindex="-1">Step 2: Confirm the deadline <a class="header-anchor" href="#step-2-confirm-the-deadline" aria-label="Permalink to &quot;Step 2: Confirm the deadline&quot;">​</a></h2><p>The deadline is set on the create form. To change it later, open the project and edit it on the configuration card.</p><p>Deadlines are visible to Owners and Managers. They are never shown to Users.</p><p>Internal and time-off projects don&#39;t need deadlines — they&#39;re ongoing.</p><hr><h2 id="step-3-assign-a-project-manager" tabindex="-1">Step 3: Assign a project manager <a class="header-anchor" href="#step-3-assign-a-project-manager" aria-label="Permalink to &quot;Step 3: Assign a project manager&quot;">​</a></h2><p>On the project&#39;s page, use <strong>PM Assignment</strong>.</p><p>This sets the project&#39;s PM and promotes them to Manager if they are currently a User. The person does not need to have messaged VERA in Slack first — the console identifies people by their record.</p><hr><h2 id="step-4-enable-tasks" tabindex="-1">Step 4: Enable tasks <a class="header-anchor" href="#step-4-enable-tasks" aria-label="Permalink to &quot;Step 4: Enable tasks&quot;">​</a></h2><p>Tasks define what kinds of work can be logged on this project. Enable the ones that apply from the project&#39;s page.</p><p>Every new project starts with <strong>Project Management</strong> already enabled, so it can receive an envelope immediately.</p><p>A project with no enabled tasks cannot receive an allocation envelope, which is the usual reason an envelope form appears with no Task dropdown.</p><hr><h2 id="step-5-create-envelopes-for-the-team-manager-or-owner" tabindex="-1">Step 5: Create envelopes for the team (Manager or Owner) <a class="header-anchor" href="#step-5-create-envelopes-for-the-team-manager-or-owner" aria-label="Permalink to &quot;Step 5: Create envelopes for the team (Manager or Owner)&quot;">​</a></h2><p>An envelope is one person&#39;s hours on one task on one project. Add them from the project&#39;s <strong>Allocations</strong> card, or from <strong>Envelopes</strong> in the left nav.</p><p>Each envelope needs a person, a task from the project&#39;s enabled set, and an hours figure. Optionally it can carry a <strong>window</strong> (the dates its hours are expected to land between) and, once it has a window, a <strong>shape</strong> — how those hours are distributed across the weeks.</p><p>The allocation bar on the project page shows the total allocated against the hours budget, and flags over- and under-allocation. On a Fixed Price project an Owner also sees the people budget — the contract divided by the target efficiency ratio — and how much of it the current envelopes commit.</p><hr><h2 id="step-6-the-team-starts-logging" tabindex="-1">Step 6: The team starts logging <a class="header-anchor" href="#step-6-the-team-starts-logging" aria-label="Permalink to &quot;Step 6: The team starts logging&quot;">​</a></h2><p>Team members can now log time, in Slack or in the console:</p><blockquote><p>&quot;3 hours on Nike Rebrand for design&quot;</p></blockquote><p>VERA confirms with an entry ID. The entry flows immediately into every report and financial calculation — there is no approval step and no month-end reconciliation.</p><p>Time logged with no envelope, or that pushes an envelope past its allocated hours, is surfaced to managers as an exception in the unresolved queue rather than being blocked.</p><hr><h2 id="retainer-and-agile-projects" tabindex="-1">Retainer and Agile projects <a class="header-anchor" href="#retainer-and-agile-projects" aria-label="Permalink to &quot;Retainer and Agile projects&quot;">​</a></h2><p>Both types are <strong>frozen for creation</strong> — new ones cannot be made on either surface. Existing retainers and agile projects continue to work, and every status check, dashboard and report behaves as it always did.</p><p>For an existing retainer, hours and contract value live on the active period child rather than the parent, and the retainer status view is the right place to read them. For an existing agile project, the same is true of the active sprint.</p>',38)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
